PREFIX=('Use case: scientific-educational. Asset type: explanatory illustration beside editable tables or teaching cards in a Turkish university UAV simulation presentation. '
        'Create one portrait 4:5 illustration, with all important content comfortably inside the frame. Primary request: ')
SUFFIX=(' Style: refined isometric engineering illustration with realistic materials and precise but uncluttered visual relationships, easy to understand at small slide scale. '
        'Palette: pale blue #EDF3FF background, navy #18365D, teal #238B88, muted gold #D79A29, natural farm greens. '
        'Objects large, ample visual breathing room, subtle shadows. No words, numbers, legends, watermarks, logos or fake application screenshots. '
        'This is a conceptual teaching drawing, never simulated-flight evidence or a measured reconstruction result. Do not add decorations unrelated to the mechanism.')
slides=json.loads((ROOT/'sunum/kaynak/slides.json').read_text(encoding='utf-8'))['slides']
targets={i+1 for i,s in enumerate(slides) if s['layout'] in ('cards','table','flow','code','formula','stats')}
assert targets==set(CONCEPTS)
assets=[{'slide':n,'title':slides[n-1]['title'],'original_layout':slides[n-1]['layout'],
         'file':f'slide-{n:02d}.png','prompt':PREFIX+concept+SUFFIX} for n,concept in CONCEPTS.items()]
manifest={'mode':'built-in image_gen','purpose':'AI-generated conceptual teaching illustrations; not simulation evidence',
          'deck_pages':len(slides),'target_pages':len(assets),'assets':assets}
(OUT/'prompts.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2),encoding='utf-8')
print(f'{len(assets)} illustration prompts prepared in {OUT}')
